/// <reference path="./sigApi.PropertyObject.d.ts" />

declare namespace SigApi {
    interface SchemeBranch {
        /**
         * Returns the compare operator
         * 
         * @returns {number} The compare operator as number constant (SIG_CONST.SCHEME_OPERATOR_...)
         */
        getCompareOperator(): number
        /**
         * Returns the object describing the result of the scheme branch
         * 
         * @returns {PropertyObject} The result of the scheme branch as propertyObject
         */
        getResultPropertyObject(): PropertyObject
        /**
         * Returns the object describing the compare value of the scheme branch
         * 
         * @returns {PropertyObject} The compare value of the scheme branch as propertyObject 
         */
        getComparePropertyObject(): PropertyObject
    }
}
